  if(action==='v26_video_upload'){const r=get(videos,b.id,c),t=tickets.get(r.id);if(r.user_id!==c.actor.id||r.status!=='sent'||!t||t.owner!==c.actor.id||t.nonce!==b.nonce||t.expires<Date.now())fail('انتهت صلاحية التسجيل؛ أعد التسجيل.');if(b.confirm_received!=='1'||!b.video?.size||!/^video\/(webm|mp4)/.test(b.video.type)||b.video.size>64*1024*1024)fail('راجع الفيديو والتأكيد قبل الإرسال.');if(window.demoReview193.failNextUpload){window.demoReview193.failNextUpload=false;fail('تعذر حفظ التسجيل التجريبي؛ يمكنك إعادة المحاولة.');}const url=URL.createObjectURL(b.video);if(media.has(r.id))URL.revokeObjectURL(media.get(r.id).url);media.set(r.id,{blob:b.video,url});r.status='recorded';r.recorded_at=now();r.file_id=++next;tickets.delete(r.id);return done({id:r.id,ok:true,local_demo:true});}
  if(action==='v26_video_objection'){const r=get(videos,b.id,c);if(r.user_id!==c.actor.id||r.status!=='sent'||!String(b.note||'').trim())fail('الإجراء غير متاح.');r.status='objection';r.body_json=JSON.stringify({...body(r),objection:b.note});tickets.delete(r.id);return done({ok:true});}
  if(action==='review193_video_download'){if(!c.superAdmin)fail('التنزيل مسموح للمشرف العام فقط.');const r=get(videos,p.id,c),m=media.get(r.id);if(!m)fail('لا يوجد تسجيل محفوظ لهذا الإقرار.');return done({url:m.url,name:'declaration-'+r.id+(m.blob.type.includes('mp4')?'.mp4':'.webm')});}
  return {handled:false};
